begin;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,aud,role)
select ('a1140000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'session114-'||n||'@verify.local',now(),'authenticated','authenticated' from generate_series(1,2) n;
insert into profiles(id,gender,hub_id,company_email,name,onboarding_step)
select id,case when email like '%1@%' then 'male'::gender else 'female'::gender end,'gangnam',email,'가상개인세션',7 from auth.users where email like 'session114-%@verify.local';
update app_settings set assistant_chat_enabled=true,assistant_memory_enabled=true,assistant_profile_edit_enabled=true;
create temporary table session_probe(label text primary key,session_id uuid,revision bigint);
select set_config('request.jwt.claim.sub','a1140000-0000-0000-0000-000000000001',true);
select ok(my_assistant_state()->>'session_id' is null,'no private session before consent');
select assistant_manager_consent(true,'manager-continuity-v2');
insert into session_probe select 'original',session_id,revision from assistant_preferences where owner_id=auth.uid();
select ok(my_assistant_state()->>'session_id' is not null,'explicit consent starts a private session');
select is(assistant_history()->>'session_id',my_assistant_state()->>'session_id','home and history share session');
select is(assistant_begin_turn('a1140000-0000-0000-0001-000000000001','첫 만남 장소가 고민이에요',(my_assistant_state()->>'revision')::bigint)->>'session_id',my_assistant_state()->>'session_id','old begin signature returns owner session');
select is((select session_id::text from assistant_turns where id='a1140000-0000-0000-0001-000000000001'),my_assistant_state()->>'session_id','turn stored in server-bound session');
select is(assistant_begin_turn('a1140000-0000-0000-0001-000000000001','첫 만남 장소가 고민이에요',(my_assistant_state()->>'revision')::bigint)->>'created','false','idempotent retry preserves receipt');
select ok(assistant_finish_turn(auth.uid(),'a1140000-0000-0000-0001-000000000001',(my_assistant_state()->>'revision')::bigint,'조용한 카페도 고려해 보세요.'),'matching owner can finish');
select assistant_save_memory(null,'주말 오후가 편해요',null,null,(my_assistant_state()->>'revision')::bigint);
select is(my_assistant_state()->>'session_id',(select session_id::text from session_probe where label='original'),'new approved memory keeps session stable');
select isnt((my_assistant_state()->>'revision')::bigint,(select revision from session_probe where label='original'),'privacy revision is independent from session identity');
select assistant_begin_turn('a1140000-0000-0000-0001-000000000002','내가 조용한 카페를 좋아한다고 했나요?',(my_assistant_state()->>'revision')::bigint);
select is(assistant_turn_context('a1140000-0000-0000-0001-000000000002')->'history'->0->>'answer','조용한 카페도 고려해 보세요.','past AI suggestion remains separately identified by answer');
select is(assistant_turn_context('a1140000-0000-0000-0001-000000000002')->'memories','["주말 오후가 편해요"]'::jsonb,'only explicit approved memory enters memory context');
select is((select count(distinct session_id)::int from assistant_turns where owner_id=auth.uid()),1,'successive turns keep one session across revision changes');
select set_config('request.jwt.claim.sub','a1140000-0000-0000-0000-000000000002',true);
select assistant_manager_consent(true,'manager-continuity-v2');
select isnt(my_assistant_state()->>'session_id',(select session_id::text from session_probe where label='original'),'different account has a different session');
select is(jsonb_array_length(assistant_history()->'turns'),0,'second account cannot read first account history');
select throws_ok($$select assistant_turn_context('a1140000-0000-0000-0001-000000000002')$$,'PT409','context unavailable','knowing turn ID does not grant context access');
select throws_ok($$select assistant_begin_turn('a1140000-0000-0000-0001-000000000002','내가 조용한 카페를 좋아한다고 했나요?',(my_assistant_state()->>'revision')::bigint)$$,'PT409','request conflict','request ID cannot rebind another account turn');
select ok(not assistant_finish_turn(auth.uid(),'a1140000-0000-0000-0001-000000000002',3,'다른 사용자의 응답'),'finish validates owner and session together');
select ok(not has_column_privilege('authenticated','assistant_preferences','session_id','update'),'client cannot select session via preferences table');
select ok(not has_function_privilege('authenticated','assistant_bind_turn_session()','execute'),'server session binding helper not callable by members');
select set_config('request.jwt.claim.sub','a1140000-0000-0000-0000-000000000001',true);
insert into session_probe select 'before-forget',session_id,revision from assistant_preferences where owner_id=auth.uid();
select assistant_forget('history');
select isnt(my_assistant_state()->>'session_id',(select session_id::text from session_probe where label='before-forget'),'forget rotates even an active conversation session');
select is(jsonb_array_length(assistant_history()->'turns'),0,'forget clears all transcript pages');
select is(jsonb_array_length(my_assistant_state()->'memories'),1,'history deletion preserves confirmed memory');
select ok(not assistant_finish_turn(auth.uid(),'a1140000-0000-0000-0001-000000000002',(select revision from session_probe where label='before-forget'),'늦게 도착한 답변'),'forget rejects late model result');
select throws_ok($$select assistant_begin_turn('a1140000-0000-0000-0001-000000000002','내가 조용한 카페를 좋아한다고 했나요?',(select revision from session_probe where label='before-forget'))$$,'PT409','context changed','old HTTP request cannot recreate erased turn');
insert into session_probe select 'empty-before-forget',session_id,revision from assistant_preferences where owner_id=auth.uid();
select assistant_forget('history');
select isnt(my_assistant_state()->>'session_id',(select session_id::text from session_probe where label='empty-before-forget'),'forget also invalidates an empty session');
select assistant_begin_turn('a1140000-0000-0000-0001-000000000003','기억을 바꾸기 전 질문',(my_assistant_state()->>'revision')::bigint);
insert into session_probe select 'before-edit',session_id,revision from assistant_preferences where owner_id=auth.uid();
select assistant_save_memory((select id from assistant_memories where owner_id=auth.uid()),'평일 저녁이 편해요',1,null,(my_assistant_state()->>'revision')::bigint);
select isnt(my_assistant_state()->>'session_id',(select session_id::text from session_probe where label='before-edit'),'memory correction clears derived transcript and rotates session');
select ok(not assistant_finish_turn(auth.uid(),'a1140000-0000-0000-0001-000000000003',(select revision from session_probe where label='before-edit'),'수정 전 정보로 만든 답변'),'memory edit fences late result');
select assistant_begin_turn('a1140000-0000-0000-0001-000000000004','만료 전 질문',(my_assistant_state()->>'revision')::bigint);
insert into session_probe select 'before-expiry',session_id,revision from assistant_preferences where owner_id=auth.uid();
update assistant_memories set expires_at=now()-interval '1 second' where owner_id=auth.uid();
select expire_private_assistant();
select is(my_assistant_state()->>'session_id',(select session_id::text from session_probe where label='before-expiry'),'expired legacy preference preserves renewed conversation archive');
select ok(not assistant_finish_turn(auth.uid(),'a1140000-0000-0000-0001-000000000004',(select revision from session_probe where label='before-expiry'),'만료된 기억의 답변'),'memory TTL rejects late result');
select is(jsonb_array_length(my_assistant_state()->'memories'),0,'expired memory not returned');
select assistant_begin_turn('a1140000-0000-0000-0001-000000000005','대화 보관 기한 검사',(my_assistant_state()->>'revision')::bigint);
update assistant_turns set expires_at=now()-interval '1 second' where id='a1140000-0000-0000-0001-000000000005';
select throws_ok($$select assistant_turn_context('a1140000-0000-0000-0001-000000000005')$$,'PT409','context unavailable','expired turn cannot supply model context');
select ok(not assistant_finish_turn(auth.uid(),'a1140000-0000-0000-0001-000000000005',(my_assistant_state()->>'revision')::bigint,'보관 기한 이후의 답변'),'expired turn cannot accept late answer');
insert into assistant_turns(id,owner_id,privacy_revision,question,answer,state,session_id)
values('a1140000-0000-0000-0001-000000000006',auth.uid(),(my_assistant_state()->>'revision')::bigint,'최근 질문','최근 답변','complete',(select session_id from session_probe where label='original'));
select is((select session_id::text from assistant_turns where id='a1140000-0000-0000-0001-000000000006'),my_assistant_state()->>'session_id','server binds even supplied stale session to current owner session');
insert into session_probe select 'before-turn-ttl',session_id,revision from assistant_preferences where owner_id=auth.uid();
select expire_private_assistant();
select is(my_assistant_state()->>'session_id',(select session_id::text from session_probe where label='before-turn-ttl'),'ordinary transcript TTL preserves stable session');
select is(jsonb_array_length(assistant_history()->'turns'),2,'expiring one turn preserves archive including failed earlier turn');
insert into profile_revision_drafts(id,owner_id,instruction,source_document,source_revision,source_fingerprint)
values('a1140000-0000-0000-0002-000000000001',auth.uid(),'가상 요청','{}',now(),'synthetic');
update profile_revision_drafts set state='approved',approved_at=now() where id='a1140000-0000-0000-0002-000000000001';
select is((select session_id::text from assistant_turns where source_id='a1140000-0000-0000-0002-000000000001'),my_assistant_state()->>'session_id','existing completion receipt binds to active conversation');
update profile_revision_drafts set state='approved' where id='a1140000-0000-0000-0002-000000000001';
select is((select count(*)::int from assistant_turns where source_id='a1140000-0000-0000-0002-000000000001'),1,'completion receipt remains idempotent');
select assistant_begin_turn('a1140000-0000-0000-0001-000000000007','철회 전 질문',(my_assistant_state()->>'revision')::bigint);
insert into session_probe select 'before-revoke',session_id,revision from assistant_preferences where owner_id=auth.uid();
select assistant_consent(false);
select ok(my_assistant_state()->>'session_id' is null,'revoke clears active session identity');
select is(jsonb_array_length(assistant_history()->'turns'),0,'revoke erases transcript and completion receipts');
select ok(not assistant_finish_turn(auth.uid(),'a1140000-0000-0000-0001-000000000007',(select revision from session_probe where label='before-revoke'),'철회 후 답변'),'revoke fences late result');
select assistant_manager_consent(true,'manager-continuity-v2');
select isnt(my_assistant_state()->>'session_id',(select session_id::text from session_probe where label='before-revoke'),'renewed consent creates a fresh session');
insert into session_probe select 'before-repeat-consent',session_id,revision from assistant_preferences where owner_id=auth.uid();
select assistant_manager_consent(true,'manager-continuity-v2');
select is(my_assistant_state()->>'session_id',(select session_id::text from session_probe where label='before-repeat-consent'),'repeated consent does not fork active session');
select assistant_begin_turn('a1140000-0000-0000-0001-000000000008','비활성화 전 질문',(my_assistant_state()->>'revision')::bigint);
insert into session_probe select 'before-inactive',session_id,revision from assistant_preferences where owner_id=auth.uid();
update profiles set account_state='banned' where id=auth.uid();
select ok((select session_id is null from assistant_preferences where owner_id=auth.uid()),'inactive account loses session identity');
select is((select count(*)::int from assistant_turns where owner_id=auth.uid()),0,'inactive account loses transcript');
select ok(not assistant_finish_turn(auth.uid(),'a1140000-0000-0000-0001-000000000008',(select revision from session_probe where label='before-inactive'),'비활성화 후 답변'),'inactive account rejects late response');
select * from finish();
rollback;
